// MinimockProduceObjectWrittenInspect logs each unmet expectation
func (m *AccessProducerServiceMock) MinimockProduceObjectWrittenInspect() {
	for _, e := range m.ProduceObjectWrittenMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AccessProducerServiceMock.ProduceObjectWritten at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterProduceObjectWrittenCounter := mm_atomic.LoadUint64(&m.afterProduceObjectWrittenCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ProduceObjectWrittenMock.defaultExpectation != nil && afterProduceObjectWrittenCounter < 1 {
		if m.ProduceObjectWrittenMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AccessProducerServiceMock.ProduceObjectWritten at\n%s", m.ProduceObjectWrittenMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AccessProducerServiceMock.ProduceObjectWritten at\n%s with params: %#v", m.ProduceObjectWrittenMock.defaultExpectation.expectationOrigins.origin, *m.ProduceObjectWrittenMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcProduceObjectWritten != nil && afterProduceObjectWrittenCounter < 1 {
		m.t.Errorf("Expected call to AccessProducerServiceMock.ProduceObjectWritten at\n%s", m.funcProduceObjectWrittenOrigin)
	}

	if !m.ProduceObjectWrittenMock.invocationsDone() && afterProduceObjectWrittenCounter > 0 {
		m.t.Errorf("Expected %d calls to AccessProducerServiceMock.ProduceObjectWritten at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ProduceObjectWrittenMock.expectedInvocations), m.ProduceObjectWrittenMock.expectedInvocationsOrigin, afterProduceObjectWrittenCounter)
	}
}

