// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *AccessProducerServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *AccessProducerServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockProduceObjectReadDone() &&
		m.MinimockProduceObjectWrittenDone()
}
